CREATE TABLE labor_portes(id TEXT PRIMARY KEY,name TEXT NOT NULL);
CREATE TABLE labor_rates(tenant_id TEXT NOT NULL REFERENCES tenants(id),porte_id TEXT NOT NULL REFERENCES labor_portes(id),hourly_rate INTEGER NOT NULL CHECK(hourly_rate>0),PRIMARY KEY(tenant_id,porte_id));
CREATE TABLE workshop_services(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL REFERENCES tenants(id),name TEXT NOT NULL,execution TEXT NOT NULL CHECK(execution IN ('internal','outsourced')),porte_id TEXT REFERENCES labor_portes(id),minutes REAL NOT NULL DEFAULT 0 CHECK(minutes>=0),price INTEGER NOT NULL DEFAULT 0 CHECK(price>=0),cost INTEGER NOT NULL DEFAULT 0 CHECK(cost>=0),pricing_mode TEXT NOT NULL DEFAULT 'time' CHECK(pricing_mode IN ('time','price')),active INTEGER NOT NULL DEFAULT 1,UNIQUE(tenant_id,id));
CREATE INDEX idx_workshop_services_tenant ON workshop_services(tenant_id,active,name);
CREATE INDEX idx_workshop_services_porte ON workshop_services(porte_id);
CREATE INDEX idx_labor_rates_porte ON labor_rates(porte_id);
ALTER TABLE vehicles ADD COLUMN service_model_id TEXT NOT NULL DEFAULT '';
ALTER TABLE vehicles ADD COLUMN service_porte_id TEXT NOT NULL DEFAULT '';
CREATE TABLE order_items_new(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,order_id TEXT NOT NULL,catalog_id TEXT,professional_id TEXT,kind TEXT NOT NULL,name TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),price INTEGER NOT NULL CHECK(price>=0),cost INTEGER NOT NULL CHECK(cost>=0),service_snapshot TEXT NOT NULL DEFAULT '',CHECK(catalog_id IS NOT NULL OR (kind='service' AND service_snapshot<>'')),FOREIGN KEY(tenant_id,order_id) REFERENCES orders(tenant_id,id),FOREIGN KEY(tenant_id,catalog_id) REFERENCES catalog(tenant_id,id),FOREIGN KEY(tenant_id,professional_id) REFERENCES professionals(tenant_id,id));
DROP TABLE order_items;
ALTER TABLE order_items_new RENAME TO order_items;
CREATE INDEX idx_items_order ON order_items(tenant_id,order_id);
UPDATE catalog SET active=0,archived_at=COALESCE(archived_at,CURRENT_TIMESTAMP) WHERE kind='service' AND archived_at IS NULL;
